package com.lmspilot.organization.api;import com.lmspilot.organization.domain.*;import com.lmspilot.support.security.InternalTokenAuthorizer;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/organization/units") public class InternalOrganizationUnitController{private final OrganizationUnitRepository repository;private final InternalTokenAuthorizer internal;public InternalOrganizationUnitController(OrganizationUnitRepository r,InternalTokenAuthorizer i){repository=r;internal=i;}@PostMapping("/validate-active") public Set<UUID> validateActive(@RequestBody ValidateOrganizationUnitsRequest in,@RequestHeader(value="X-Service-Token",required=false)String token){internal.require(token);if(in.ids().isEmpty())return Set.of();Set<UUID> out=new HashSet<>();for(var e:repository.findAllById(in.ids()))if(e.getStatus()==OrganizationUnitStatus.ACTIVE)out.add(e.getId());return out;}}
